sys_script_include.script:
var CardRepository = Class.create();
CardRepository.prototype = {
    initialize: function() {},

    findCardById: function(cardId) {

        var grCard = new GlideRecord('vtb_card');
        var cardExist = grCard.get('u_trello_card_id',cardId);

        if (cardExist)
            return grCard;
        else return null;
    },

    findTaskById: function(taskId) {

        var grTask = new GlideRecord('vtb_task');
        var taskExist = grTask.get(taskId);

        if (taskExist)
            return grTask;
		else return null;
    },

    save: function(cardObj) {
        cardObj.update();
    },

	createNewCard: function(){
		var grCard = new GlideRecord('vtb_card');
		grCard.initialize();
		//var newCard = grCard.insert();
		return grCard;
	},

	createNewTask: function(){

		var grTask = new GlideRecord('vtb_task');
		grTask.initialize();
		//var newTask = grTask.insert();
		return grTask;

	},

    getListID: function(listName){

        // Default lane is TODO / Do zrobienia
        var DEFAULT_LANE = '1d424523c3fa72101cae1933e4013137';

        var grList = new GlideRecord('vtb_lane');
        grList.addQuery('name', listName);
        grList.query();

        return grList.next() ? grList.sys_id : DEFAULT_LANE;

    },

    type: 'CardRepository'
};
